/* ================= اللعبة 2: لعبة التكوين ================= */
const TOTAL_ROUNDS = ROUND_SEQUENCE.length;
function ConstructGame({ sfx, onFinish }) {
  const [roundNum, setRoundNum] = useState(1);
  const [usedCombos, setUsedCombos] = useState([]);
  const [round, setRound] = useState(() => buildConstructRound(ROUND_SEQUENCE[0], []));
  const [slots, setSlots] = useState(() => Array(round.type.catSeq.length).fill(null));
  const [wrongId, setWrongId] = useState(null);
  const [burst, setBurst] = useState(false);
  const [showNote, setShowNote] = useState(false);
  const [cleanRound, setCleanRound] = useState(true);
  const [cleanCount, setCleanCount] = useState(0);
  const [done, setDone] = useState(false);

  const step = slots.findIndex((s) => s === null);
  const catSeq = round.type.catSeq;
  const requiredCat = step === -1 ? null : catSeq[step];
  const chosenWords = slots.filter((s) => s).map((s) => s.w);

  function nextRound(nextUsed) {
    setBurst(false); setShowNote(false);
    if (roundNum >= TOTAL_ROUNDS) { setDone(true); return; }
    const r = buildConstructRound(ROUND_SEQUENCE[roundNum], nextUsed);
    setRoundNum((n) => n + 1); setRound(r); setSlots(Array(r.type.catSeq.length).fill(null)); setCleanRound(true);
  }
  function tapTile(tile) {
    const alreadyUsed = slots.some((s) => s && s.id === tile.id);
    const wouldBe = [...chosenWords, tile.w];
    if (!alreadyUsed && tile.cat === requiredCat && isValidPrefix(round.type, wouldBe)) {
      const newSlots = [...slots]; newSlots[step] = tile; setSlots(newSlots);
      const isLast = step === catSeq.length - 1;
      if (isLast) {
        sfx.playRoundComplete(); vibrate([25, 40, 25, 40, 70]); setBurst(true);
        if (round.type.note) setShowNote(true);
        setCleanCount((c) => c + (cleanRound ? 1 : 0));
        const nextUsed = [...usedCombos, wouldBe.join("|")];
        setUsedCombos(nextUsed);
        setTimeout(() => nextRound(nextUsed), round.type.note ? 2200 : 1100);
      } else { sfx.playCorrectTap(); vibrate(20); }
    } else {
      sfx.playWrongTap(); vibrate([15, 30, 15, 30]); setWrongId(tile.id); setCleanRound(false);
      setTimeout(() => setWrongId(null), 420);
    }
  }
  const stars = cleanCount === TOTAL_ROUNDS ? 3 : cleanCount >= 7 ? 2 : cleanCount >= 4 ? 1 : 0;

  if (done) {
    return (
      <>
        <Header eyebrow="سفينة الإعراب · الجملة" title="لعبة التكوين" />
        <div className="text-center py-10 px-7">
          <div className="flex justify-center gap-2 mb-4">
            {[0, 1, 2].map((i) => <span key={i} style={{ fontSize: 32, color: i < stars ? "#F5A623" : "#DDD8E8" }}>★</span>)}
          </div>
          <p className="text-xl mb-3" style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700 }}>أتممت التكوين!</p>
          <p className="text-sm mb-7" style={{ color: "#545B68" }}>كوّنت {cleanCount} من {TOTAL_ROUNDS} جمل من أول محاولة</p>
          <button onClick={() => onFinish(stars)} className="px-7 py-2.5 rounded-full text-sm font-bold inline-flex items-center gap-2 mx-auto" style={{ background: "linear-gradient(135deg,#F5A623,#D9860F)", color: "#2A1608" }}>
            المتابعة <ChevronLeft size={15} />
          </button>
        </div>
      </>
    );
  }

  return (
    <>
      <Header eyebrow="سفينة الإعراب · الجملة" title="لعبة التكوين" />
      <div className="px-4 pb-6">
        <div className="flex items-center justify-center gap-2 mb-4">
          {Array.from({ length: TOTAL_ROUNDS }).map((_, i) => (
            <div key={i} className="rounded-full" style={{ width: i + 1 === roundNum ? 18 : 6, height: 6, background: i + 1 < roundNum ? "#4ADE80" : i + 1 === roundNum ? "#F5A623" : "#DDD8E8" }} />
          ))}
        </div>
        <p key={roundNum} className="question-pop text-center mb-1" style={{ fontSize: 19, fontWeight: 900, color: "#F5A623", fontFamily: "'Amiri', serif" }}>{round.type.title}</p>
        <p className="text-center text-xs mb-5" style={{ color: "#545B68" }}>
          {step === 0 ? round.type.hint : requiredCat ? `أكمل بـ${STEP_HINT[requiredCat]}` : ""}
        </p>
        <div className="flex gap-2 justify-center mb-5 relative">
          {burst && (
            <div className="absolute inset-x-0 -top-2 flex justify-center z-20 pointer-events-none">
              <div className="match-burst px-6 py-2 rounded-full text-lg font-bold" style={{ background: "#F5A623", color: "#202430" }}>✦ ممتاز ✦</div>
            </div>
          )}
          {slots.map((s, i) => (
            <div key={i} className={`rounded-2xl flex items-center justify-center flex-1 glow-pulse ${s ? "slot-fill" : ""}`} style={{ height: 82, background: s ? "#FFF3D6" : "#F5F5F7", border: s ? `3px solid ${CAT_COLOR[s.cat]}` : "2px dashed rgba(255,215,120,0.5)" }}>
              {s && <span style={{ fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 19, color: "#202430" }}>{s.w}</span>}
            </div>
          ))}
        </div>
        {showNote && (
          <div className="rounded-xl px-4 py-3 mb-5 text-center text-xs leading-relaxed" style={{ background: "rgba(255,215,120,0.12)", border: "1px solid rgba(255,215,120,0.4)", color: "#FFE8B0" }}>
            {round.type.note}
          </div>
        )}
        <div className="grid grid-cols-3 gap-2">
          {round.tiles.filter((t) => !slots.some((s) => s && s.id === t.id)).map((t) => (
            <button key={t.id} onClick={() => tapTile(t)} className={`tile-in rounded-xl py-3.5 flex items-center justify-center text-center ${wrongId === t.id ? "shake-wrong" : ""}`}
              style={{ background: wrongId === t.id ? "rgba(200,60,60,0.4)" : "#F1F4F7", border: `1.5px solid ${wrongId === t.id ? "#E88" : "rgba(255,215,120,0.5)"}`, color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 15, minHeight: 52 }}>
              {t.w}
            </button>
          ))}
        </div>
      </div>
    </>
  );
}

/* ================= اللعبة 3: لعبة التحويل ================= */
const MUTHANNA = [
  { s: "معلمٌ", t: "معلمانِ" }, { s: "طالبٌ", t: "طالبانِ" },
  { s: "كتابٌ", t: "كتابانِ" }, { s: "قلمٌ", t: "قلمانِ" },
];
const JAM_MUTHAKKAR_SALIM = [
  { s: "معلمٌ", t: "معلمونَ" }, { s: "مسلمٌ", t: "مسلمونَ" },
  { s: "مهندسٌ", t: "مهندسونَ" }, { s: "مجتهدٌ", t: "مجتهدونَ" },
];
const JAM_MUANNATH_SALIM = [
  { s: "معلمةٌ", t: "معلماتٌ" }, { s: "طالبةٌ", t: "طالباتٌ" },
  { s: "مسلمةٌ", t: "مسلماتٌ" }, { s: "مجتهدةٌ", t: "مجتهداتٌ" },
];
const JAM_TAKSEER = [
  { s: "كتابٌ", t: "كتبٌ" }, { s: "رجلٌ", t: "رجالٌ" },
  { s: "قلمٌ", t: "أقلامٌ" }, { s: "بيتٌ", t: "بيوتٌ" }, { s: "ولدٌ", t: "أولادٌ" },
];
const TRANSFORM_TYPES = [
  { key: "muthanna", label: "مثنى", pairs: MUTHANNA, rule: "المثنى: نزيد ألفًا ونونًا في الرفع" },
  { key: "jsalim", label: "جمع مذكر سالم", pairs: JAM_MUTHAKKAR_SALIM, rule: "جمع مذكر سالم: نزيد واوًا ونونًا في الرفع" },
  { key: "msalim", label: "جمع مؤنث سالم", pairs: JAM_MUANNATH_SALIM, rule: "جمع مؤنث سالم: نزيد ألفًا وتاءً" },
  { key: "takseer", label: "جمع تكسير", pairs: JAM_TAKSEER, rule: "جمع تكسير: تتغيّر بنية الكلمة نفسها، لا مجرد زيادة" },
];
const TRANSFORM_ROUNDS = 8;

function buildTransformRound() {
  const type = shuffle(TRANSFORM_TYPES)[0];
  const pair = shuffle(type.pairs)[0];
  const correct = pair.t;
  const options = new Set([correct]);
  // فخ ١: نفس الكلمة بنوع تحويل مختلف (إن وُجد)
  const otherType = shuffle(TRANSFORM_TYPES.filter((t) => t.key !== type.key))[0];
  const sameWordOther = otherType.pairs.find((p) => p.s === pair.s);
  if (sameWordOther) options.add(sameWordOther.t);
  // فخ ٢: نفس نوع التحويل لكن لكلمة أخرى
  const otherPair = shuffle(type.pairs.filter((p) => p.s !== pair.s))[0];
  if (otherPair) options.add(otherPair.t);
  while (options.size < 3) {
    const rnd = shuffle(TRANSFORM_TYPES.flatMap((t) => t.pairs.map((p) => p.t)))[0];
    options.add(rnd);
  }
  return { type, pair, correct, options: shuffle([...options]).slice(0, 3) };
}

function TransformGame({ sfx, onFinish }) {
  const [roundNum, setRoundNum] = useState(1);
  const [round, setRound] = useState(() => buildTransformRound());
  const [selected, setSelected] = useState(null);
  const [feedback, setFeedback] = useState(null);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  function pick(opt) {
    if (feedback) return;
    setSelected(opt);
    const correct = opt === round.correct;
    setFeedback(correct ? "correct" : "wrong");
    if (correct) { sfx.playCorrectTap(); vibrate(20); setScore((s) => s + 1); }
    else { sfx.playWrongTap(); vibrate([15, 30, 15, 30]); }
    setTimeout(() => next(), 1500);
  }
  function next() {
    setRoundNum((prevRoundNum) => {
      if (prevRoundNum >= TRANSFORM_ROUNDS) { setDone(true); return prevRoundNum; }
      setRound(buildTransformRound()); setSelected(null); setFeedback(null);
      return prevRoundNum + 1;
    });
  }
  const stars = score === TRANSFORM_ROUNDS ? 3 : score >= 6 ? 2 : score >= 4 ? 1 : 0;

  if (done) {
    return (
      <>
        <Header eyebrow="سفينة الإعراب · التحويل" title="لعبة التحويل" />
        <div className="text-center py-10 px-7">
          <div className="flex justify-center gap-2 mb-4">
            {[0, 1, 2].map((i) => <span key={i} style={{ fontSize: 32, color: i < stars ? "#F5A623" : "#DDD8E8" }}>★</span>)}
          </div>
          <p className="text-xl mb-3" style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700 }}>أتممت التحويل!</p>
          <p className="text-sm mb-7" style={{ color: "#545B68" }}>أجبت بشكل صحيح على {score} من {TRANSFORM_ROUNDS}</p>
          <button onClick={() => onFinish(stars)} className="px-7 py-2.5 rounded-full text-sm font-bold inline-flex items-center gap-2 mx-auto" style={{ background: "linear-gradient(135deg,#F5A623,#D9860F)", color: "#2A1608" }}>
            المتابعة <ChevronLeft size={15} />
          </button>
        </div>
      </>
    );
  }

  return (
    <>
      <Header eyebrow="سفينة الإعراب · التحويل" title="لعبة التحويل" />
      <div className="px-4 pb-6">
        <div className="flex items-center justify-center gap-3 mb-5">
          <div className="flex items-center gap-2">
            {Array.from({ length: TRANSFORM_ROUNDS }).map((_, i) => (
              <div key={i} className="rounded-full" style={{ width: i + 1 === roundNum ? 16 : 6, height: 6, background: i + 1 < roundNum ? "#4ADE80" : i + 1 === roundNum ? "#F5A623" : "#DDD8E8" }} />
            ))}
          </div>
          <span className="text-xs font-bold px-2.5 py-1 rounded-full" style={{ background: "rgba(255,215,120,0.15)", color: "#F5A623", border: "1px solid rgba(255,215,120,0.4)" }}>
            {score} نقطة
          </span>
        </div>
        <p key={roundNum} className="question-pop text-center mb-2" style={{ fontSize: 15, fontWeight: 700, color: "#545B68" }}>
          حوّل هذه الكلمة إلى <span style={{ color: "#F5A623" }}>{round.type.label}</span>
        </p>
        <p className="text-center mb-6" style={{ fontSize: 34, fontFamily: "'Amiri', serif", fontWeight: 700, color: "#202430" }}>{round.pair.s}</p>

        <div className="flex flex-col gap-2.5 mb-5">
          {round.options.map((opt) => {
            const isPicked = opt === selected;
            const isAnswer = opt === round.correct;
            let bg = "#F1F4F7", border = "rgba(255,215,120,0.5)", color = "#202430";
            if (feedback && isAnswer) { bg = "rgba(74,222,128,0.3)"; border = "#4ADE80"; color = "#EAFBEF"; }
            else if (feedback && isPicked) { bg = "rgba(200,60,60,0.4)"; border = "#E88"; color = "#FBEAEA"; }
            return (
              <button key={opt} onClick={() => pick(opt)} disabled={!!feedback}
                className="rounded-xl py-3 text-center transition-all"
                style={{ background: bg, border: `1.5px solid ${border}`, color, fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 20 }}>
                {opt}
              </button>
            );
          })}
        </div>

        {feedback && (
          <div className="rounded-xl px-4 py-3 mb-4 text-center text-xs leading-relaxed" style={{ background: "rgba(255,215,120,0.1)", border: "1px solid rgba(255,215,120,0.35)", color: "#FFE8B0" }}>
            {round.type.rule}
          </div>
        )}

        <div className="flex justify-center" style={{ minHeight: 40 }}>
          {!feedback && <span className="text-xs" style={{ color: "#9C7A4A" }}>اختر التحويل الصحيح</span>}
        </div>
      </div>
    </>
  );
}

/* ================= اللعبة 4: الفاعل ================= */
const FAEIL_SENTENCES = [
  { verb: "كتبَ", fail: "محمدٌ", maf: "الدرسَ" },
  { verb: "أكلَ", fail: "الطفلُ", maf: "التفاحةَ" },
  { verb: "قرأَ", fail: "التلميذُ", maf: "الكتابَ" },
  { verb: "فتحَ", fail: "البوابُ", maf: "البابَ" },
  { verb: "غسلَ", fail: "الولدُ", maf: "يدَه" },
  { verb: "زرعَ", fail: "الفلاحُ", maf: "الأرضَ" },
  { verb: "بنى", fail: "العاملُ", maf: "الجدارَ" },
  { verb: "حفظَ", fail: "الطالبُ", maf: "القصيدةَ" },
];
