const FAEIL_RULE = "الفاعل: اسمٌ مرفوعٌ دائمًا، دلّ على من قام بالفعل أو اتصف به";

function buildFaeilRound(sentence) {
  return { sentence, options: shuffle([sentence.verb, sentence.fail, sentence.maf]) };
}

