    setSelected(opt);
    const correct = opt === round.sentence.fail;
    setFeedback(correct ? "correct" : "wrong");
    if (correct) { sfx.playCorrectTap(); vibrate(20); setScore((s) => s + 1); }
    else { sfx.playWrongTap(); vibrate([15, 30, 15, 30]); }
    setTimeout(() => next(), 1500);
