/* ================= اللعبة 5: الناسخ الأول (كان وأخواتها) ================= */
const KANA_SENTENCES = [
  { subj: "الطقسُ", subjAcc: "الطقسَ", khabar: "جميلٌ", khabarAcc: "جميلاً" },
  { subj: "الجوُّ", subjAcc: "الجوَّ", khabar: "باردٌ", khabarAcc: "باردًا" },
  { subj: "الامتحانُ", subjAcc: "الامتحانَ", khabar: "سهلٌ", khabarAcc: "سهلاً" },
  { subj: "الطالبُ", subjAcc: "الطالبَ", khabar: "مجتهدٌ", khabarAcc: "مجتهدًا" },
  { subj: "البيتُ", subjAcc: "البيتَ", khabar: "كبيرٌ", khabarAcc: "كبيرًا" },
  { subj: "الكتابُ", subjAcc: "الكتابَ", khabar: "مفيدٌ", khabarAcc: "مفيدًا" },
  { subj: "الطعامُ", subjAcc: "الطعامَ", khabar: "لذيذٌ", khabarAcc: "لذيذًا" },
  { subj: "الرجلُ", subjAcc: "الرجلَ", khabar: "كريمٌ", khabarAcc: "كريمًا" },
];
const KANA_ROUNDS = KANA_SENTENCES.length;
const KANA_SISTERS = ["كانَ", "أصبحَ", "أضحى", "أمسى", "ظلَّ", "باتَ", "صارَ", "ليسَ"];
const KANA_RULE = "كانَ وأخواتها: كلها ترفع المبتدأ (ويسمى اسمها) وتنصب الخبر (ويسمى خبرها)";

function buildKanaRound(s, sister) {
  const correct = `${sister} ${s.subj} ${s.khabarAcc}`;
  const wrong1 = `${sister} ${s.subjAcc} ${s.khabar}`; // عكس الحكم
  const wrong2 = `${sister} ${s.subj} ${s.khabar}`; // لم يتغيّر الخبر
  return { s, sister, correct, options: shuffle([correct, wrong1, wrong2]) };
}

function KanaGame({ sfx, onFinish }) {
  const orderRef = useRef(shuffle(KANA_SENTENCES));
  const sistersRef = useRef(shuffle(KANA_SISTERS));
  const [roundNum, setRoundNum] = useState(1);
  const [round, setRound] = useState(() => buildKanaRound(orderRef.current[0], sistersRef.current[0]));
  const [selected, setSelected] = useState(null);
  const [feedback, setFeedback] = useState(null);
  const [score, setScore] = useState(0);
  const [done, setDone] = useState(false);

  function pick(opt) {
    if (feedback) return;
    setSelected(opt);
    const correct = opt === round.correct;
    setFeedback(correct ? "correct" : "wrong");
    if (correct) { sfx.playCorrectTap(); vibrate(20); setScore((s) => s + 1); }
    else { sfx.playWrongTap(); vibrate([15, 30, 15, 30]); }
    setTimeout(() => next(), 1600);
  }
  function next() {
    setRoundNum((prevRoundNum) => {
      if (prevRoundNum >= KANA_ROUNDS) { setDone(true); return prevRoundNum; }
      setRound(buildKanaRound(orderRef.current[prevRoundNum], sistersRef.current[prevRoundNum])); setSelected(null); setFeedback(null);
      return prevRoundNum + 1;
    });
  }
  const stars = score === KANA_ROUNDS ? 3 : score >= 6 ? 2 : score >= 4 ? 1 : 0;

  if (done) {
    return (
      <>
        <Header eyebrow="سفينة الإعراب · النواسخ" title="الناسخ الأول" />
        <div className="text-center py-10 px-7">
          <div className="flex justify-center gap-2 mb-4">
            {[0, 1, 2].map((i) => <span key={i} style={{ fontSize: 32, color: i < stars ? "#F5A623" : "#DDD8E8" }}>★</span>)}
          </div>
          <p className="text-xl mb-3" style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700 }}>أتممت كان وأخواتها!</p>
          <p className="text-sm mb-7" style={{ color: "#545B68" }}>أجبت بشكل صحيح على {score} من {KANA_ROUNDS}</p>
          <button onClick={() => onFinish(stars)} className="px-7 py-2.5 rounded-full text-sm font-bold inline-flex items-center gap-2 mx-auto" style={{ background: "linear-gradient(135deg,#F5A623,#D9860F)", color: "#2A1608" }}>
            إنهاء المرحلة <ChevronLeft size={15} />
          </button>
        </div>
      </>
    );
  }

  return (
    <>
      <Header eyebrow="سفينة الإعراب · النواسخ" title="الناسخ الأول: كانَ وأخواتها" />
      <div className="px-4 pb-6">
        <div className="flex items-center justify-center gap-3 mb-5">
          <div className="flex items-center gap-2">
            {Array.from({ length: KANA_ROUNDS }).map((_, i) => (
              <div key={i} className="rounded-full" style={{ width: i + 1 === roundNum ? 16 : 6, height: 6, background: i + 1 < roundNum ? "#4ADE80" : i + 1 === roundNum ? "#F5A623" : "#DDD8E8" }} />
            ))}
          </div>
          <span className="text-xs font-bold px-2.5 py-1 rounded-full" style={{ background: "rgba(255,215,120,0.15)", color: "#F5A623", border: "1px solid rgba(255,215,120,0.4)" }}>
            {score} نقطة
          </span>
        </div>

        <p key={roundNum} className="question-pop text-center mb-2" style={{ fontSize: 15, fontWeight: 700, color: "#545B68" }}>
          الجملة الأصل: <span style={{ color: "#F5A623" }}>{round.s.subj} {round.s.khabar}</span>
        </p>
        <p className="text-center mb-6 text-xs" style={{ color: "#7A8496" }}>
          إذا دخلت عليها "<span style={{ color: "#F5A623" }}>{round.sister}</span>"، ما الصياغة الصحيحة؟
        </p>

        <div className="flex flex-col gap-2.5 mb-5">
          {round.options.map((opt) => {
            const isPicked = opt === selected;
            const isAnswer = opt === round.correct;
            let bg = "#F1F4F7", border = "rgba(255,215,120,0.5)", color = "#202430";
            if (feedback && isAnswer) { bg = "rgba(74,222,128,0.3)"; border = "#4ADE80"; color = "#EAFBEF"; }
            else if (feedback && isPicked) { bg = "rgba(200,60,60,0.4)"; border = "#E88"; color = "#FBEAEA"; }
            return (
              <button key={opt} onClick={() => pick(opt)} disabled={!!feedback}
                className="rounded-xl py-3 text-center transition-all"
                style={{ background: bg, border: `1.5px solid ${border}`, color, fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 19 }}>
                {opt}
              </button>
            );
          })}
        </div>

        {feedback && (
          <div className="rounded-xl px-4 py-3 mb-4 text-center text-xs leading-relaxed" style={{ background: "rgba(255,215,120,0.1)", border: "1px solid rgba(255,215,120,0.35)", color: "#FFE8B0" }}>
            {KANA_RULE}
          </div>
        )}

        <div className="flex justify-center" style={{ minHeight: 40 }}>
          {!feedback && <span className="text-xs" style={{ color: "#9C7A4A" }}>اختر الصياغة الصحيحة</span>}
        </div>
      </div>
    </>
  );
}

