const KHANJAR_PARTS = [
  { stageId: 1, key: "miqbad", label: "المقبض", Icon: MiqbadIcon },
  { stageId: 2, key: "kab", label: "الكعب", Icon: KabIcon },
  { stageId: 3, key: "tawq", label: "الطوق", Icon: TawqIcon },
  { stageId: 4, key: "nasla", label: "النصلة", Icon: NaslaIcon },
  { stageId: 5, key: "bazim", label: "البزيم", Icon: BazimIcon },
  { stageId: 6, key: "halqa", label: "حلقة", Icon: HalqaIcon },
  { stageId: 7, key: "tams", label: "الطمس", Icon: TamsIcon },
  { stageId: 8, key: "hizam", label: "الحزام", Icon: HizamIcon },
  { stageId: 9, key: "qitaa", label: "القطاعة", Icon: QitaaIcon },
  { stageId: 10, key: "sailan", label: "سيلان", Icon: SailanIcon },
  { stageId: 11, key: "badira", label: "البادرة", Icon: BadiraIcon },
];
function isPartCollected(stages, part) {
  return stages.find((s) => s.id === part.stageId)?.status === "done";
}

const INITIAL_STAGES = [
  { id: 1, name: "الكلمات", lesson: "أقسام الكلام وعلاماته", icon: "🔤", status: "done", stars: 3 },
  { id: 2, name: "الكلمات المتماثلة", lesson: "تثبيت أقسام الكلام", icon: "🧲", status: "done", stars: 0 },
  { id: 3, name: "علامات الاسم", lesson: "الجر، التنوين، النداء، أل، الإسناد", icon: "🏷️", status: "current", stars: 0 },
  { id: 4, name: "علامات الفعل", lesson: "قد، السين، سوف، تاء التأنيث، تاء الفاعل", icon: "🏷️", status: "locked", stars: 0 },
  { id: 5, name: "النكرة والمعرفة", lesson: "أنواع المعارف السبعة وعلامة النكرة", icon: "🔎", status: "locked", stars: 0 },
  { id: 6, name: "الفراسة", lesson: "التمييز بين الجملة الاسمية والفعلية", icon: "⚡", status: "locked", stars: 0 },
  { id: 7, name: "الأزمنة", lesson: "ماضٍ، مضارع، أمر", icon: "⏳", status: "locked", stars: 0 },
  { id: 8, name: "التكوين", lesson: "الجملة وتقسيمها", icon: "🧩", status: "locked", stars: 0 },
  { id: 9, name: "التحويل", lesson: "أنواع المفرد (مثنى وجمع)", icon: "🔁", status: "locked", stars: 0 },
  { id: 10, name: "الفاعل", lesson: "الفاعل من المرفوعات", icon: "🎯", status: "locked", stars: 0 },
  { id: 11, name: "الناسخ الأول", lesson: "كان وأخواتها", icon: "🔮", status: "locked", stars: 0 },
];

/* المستويات — كل مستوى صفحة منفصلة، لا يُفتح إلا بعد إتمام الذي قبله بالكامل */
const LEVELS = [
  { id: 1, name: "من ريسوت إلى صحار", range: [1, 7] },
  { id: 2, name: "من الرستاق إلى صور", range: [8, 11] },
];
function levelOf(stageId) {
  return LEVELS.find((l) => stageId >= l.range[0] && stageId <= l.range[1]);
}
function relativeIndex(stageId) {
  const lvl = levelOf(stageId);
  return lvl ? stageId - lvl.range[0] : 0;
}

/* محطات الرحلة الحقيقية — إحداثيات نسبية (٠-١) على صورة خريطة عُمان الحقيقية،
   مدقَّقة ومصحَّحة من خط الطول/العرض ثم من ملاحظات ميدانية مباشرة */
const STATIONS = {
  1: { name: "ريسوت", x: 0.318, y: 0.909 },
  2: { name: "هيماء", x: 0.525, y: 0.640 },
  3: { name: "نزوى", x: 0.639, y: 0.370 },
  4: { name: "عبري", x: 0.535, y: 0.368 },
  5: { name: "البريمي", x: 0.500, y: 0.265 },
  6: { name: "خصب", x: 0.535, y: 0.115 },
  7: { name: "صحار", x: 0.575, y: 0.263 },
  8: { name: "الرستاق", x: 0.615, y: 0.345 },
  9: { name: "مسقط", x: 0.755, y: 0.305 },
  10: { name: "إبراء", x: 0.730, y: 0.392 },
  11: { name: "صور", x: 0.821, y: 0.403 },
};

export default function App() {
  const [appPhase, setAppPhase] = useState("playing"); // title | playing
  const [currentLevel, setCurrentLevel] = useState(1);
  const [levelComplete, setLevelComplete] = useState(false);
  const [tab, setTab] = useState("home"); // home | chest | trophies | challenges | profile
  const [screen, setScreen] = useState("map"); // map | stage1 | stage2
  const [stages, setStages] = useState(INITIAL_STAGES);
  const [toast, setToast] = useState(null);
  const [adminMode, setAdminMode] = useState(false);
  const [usedWords, setUsedWords] = useState([]);
  function markWordsUsed(words) {
    setUsedWords((prev) => [...prev, ...words]);
  }
  const [camelIndex, setCamelIndex] = useState(() => {
    const idx = INITIAL_STAGES.findIndex((s) => s.status === "current");
    return idx === -1 ? 0 : relativeIndex(idx + 1);
  });
  const [walking, setWalking] = useState(false);
  const sfx = useSfx();

  function tapStage(stage) {
    const accessible = stage.status !== "locked" || adminMode;
    if (!accessible) {
      setToast(`أكمل مرحلة "${stages.find((s) => s.id === stage.id - 1)?.name}" أولاً`);
      setTimeout(() => setToast(null), 1800);
      return;
    }
    sfx.ensureCtx();
    if (stage.id === 1) { setScreen("stage1"); return; }
    if (stage.id === 2) { setScreen("stage2"); return; }
    if (stage.id === 3) { setScreen("stage3"); return; }
    if (stage.id === 4) { setScreen("stage4"); return; }
    if (stage.id === 5) { setScreen("stage5"); return; }
    if (stage.id === 6) { setScreen("stage6"); return; }
    if (stage.id === 7) { setScreen("stage7"); return; }
    if (stage.id === 8) { setScreen("stage8"); return; }
    if (stage.id === 9) { setScreen("stage9"); return; }
    if (stage.id === 10) { setScreen("stage10"); return; }
    if (stage.id === 11) { setScreen("stage11"); return; }
    setToast("هذه المرحلة قيد الإعداد حاليًا في مشروعنا");
    setTimeout(() => setToast(null), 1800);
  }

  function finishStage(stageId, stars) {
    setStages((prev) =>
      prev.map((s) => {
        if (s.id === stageId) return { ...s, status: "done", stars };
        if (s.id === stageId + 1 && s.status === "locked") return { ...s, status: "current" };
        return s;
      })
    );
    setScreen("map");
    const st = STATIONS[stageId];
    if (st) {
      setToast(`📍 وصلت إلى ${st.name}!`);
      setTimeout(() => setToast(null), 2400);
    }
    const level = levelOf(stageId);
    const isLastOfLevel = level && stageId === level.range[1];
    if (isLastOfLevel) {
      // آخر مرحلة في المستوى — احتفال بإتمام المستوى كاملاً بدل السير للمرحلة التالية
      setTimeout(() => setLevelComplete(true), 1300);
    } else {
      // نمهل الطالب لحظة ليرى الخريطة، ثم يمشي الجمل بوضوح إلى المرحلة التالية
      setTimeout(() => {
        setWalking(true);
        setCamelIndex(relativeIndex(stageId + 1));
        setTimeout(() => setWalking(false), 1400);
      }, 500);
    }
  }

  function goToNextLevel() {
    setCurrentLevel((l) => l + 1);
    setLevelComplete(false);
    setCamelIndex(0);
    setScreen("map");
  }

  return (
    <div dir="rtl" className="min-h-screen w-full flex items-center justify-center p-4" style={{ background: "#F3ECDD", fontFamily: "'Cairo', sans-serif" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Aref+Ruqaa:wght@400;700&family=Cairo:wght@400;500;600;700;900&family=Reem+Kufi:wght@400;600&display=swap');
        @keyframes tileIn { 0% { opacity:0; transform: scale(0.7) translateY(10px);} 100% { opacity:1; transform: scale(1) translateY(0);} }
        @keyframes matchBurst { 0% { transform: scale(0.6); opacity:0;} 40% { transform: scale(1.15); opacity:1;} 100% { transform: scale(1.4); opacity:0;} }
        @keyframes glowPulse { 0%,100% { box-shadow: 0 0 8px 2px rgba(255,215,120,0.4);} 50% { box-shadow: 0 0 20px 8px rgba(255,215,120,0.75);} }
        @keyframes slotFill { 0% { transform: scale(0.5); opacity:0;} 100% { transform: scale(1); opacity:1;} }
        @keyframes shakeWrong { 0%,100% { transform: translateX(0);} 25% { transform: translateX(-6px);} 75% { transform: translateX(6px);} }
        @keyframes questionPop { 0% { transform: scale(0.9); opacity:0.6;} 100% { transform: scale(1); opacity:1;} }
        @keyframes pulseGlowStage { 0%,100% { box-shadow: 0 0 10px 3px rgba(255,215,120,0.4);} 50% { box-shadow: 0 0 20px 8px rgba(255,215,120,0.75);} }
        @keyframes fadeIn { 0% { opacity:0; transform: translateY(8px);} 100% { opacity:1; transform: translateY(0);} }
        @keyframes toastIn { 0% { opacity:0; transform: translateY(10px) translateX(-50%);} 100% { opacity:1; transform: translateY(0) translateX(-50%);} }
        .tile-in { animation: tileIn 300ms ease both; }
        .match-burst { animation: matchBurst 900ms ease-out forwards; }
        .glow-pulse { animation: glowPulse 2.2s ease-in-out infinite; }
        .slot-fill { animation: slotFill 250ms ease; }
        .shake-wrong { animation: shakeWrong 400ms ease-in-out; }
        .question-pop { animation: questionPop 300ms ease; }
        .pulse-glow-stage { animation: pulseGlowStage 1.8s ease-in-out infinite; }
        @keyframes camelBob { 0%,100% { transform: translateX(-50%) translateY(0) rotate(-4deg);} 50% { transform: translateX(-50%) translateY(-6px) rotate(4deg);} }
        .camel-bob { animation: camelBob 2.2s ease-in-out infinite; }
        @keyframes signBlink { 0%,100% { opacity: 1; } 50% { opacity: 0.45; } }
        .sign-blink { animation: signBlink 0.9s ease-in-out infinite; }
        .fade-in { animation: fadeIn 400ms ease; }
        .toast-in { animation: toastIn 250ms ease; }
        @media (prefers-reduced-motion: reduce) { * { animation: none !important; } }
      `}</style>

      <div className="w-full max-w-sm rounded-3xl overflow-hidden relative flex flex-col" style={{ boxShadow: "0 30px 80px -15px rgba(0,0,0,0.35), 0 0 0 1px #EFB84E inset", maxHeight: 680, background: "#FFFFFF" }}>

        {appPhase === "title" ? (
          <div className="flex-1 flex flex-col items-center justify-center text-center px-8 py-16 fade-in">
            <p style={{ fontSize: 46 }} className="mb-4">⚔️</p>
            <p className="text-xs tracking-[0.3em] mb-2" style={{ color: "#D9860F", fontFamily: "'Amiri', serif" }}>سفينة الإعراب</p>
            <h1 className="text-3xl mb-3" style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700 }}>لغة الضياء</h1>
            <p className="text-sm mb-10" style={{ color: "#545B68" }}>رحلتك لتعلّم النحو العربي بالتشويق والمتعة تبدأ الآن</p>
            <button
              onClick={() => setAppPhase("playing")}
              className="px-9 py-4 rounded-full text-base font-bold inline-flex items-center gap-2"
              style={{ background: "linear-gradient(135deg,#F5A623,#D9860F)", color: "#2A1608", boxShadow: "0 10px 24px -8px rgba(217,134,15,0.5)" }}
            >
              <Sparkles size={18} /> هيا نتعلم النحو
            </button>
          </div>
        ) : (
        <>
        <img
          src={OMAN_MAP_IMG}
          alt=""
          className="absolute inset-0 w-full h-full object-cover pointer-events-none"
          style={{ opacity: 0.09, zIndex: 0 }}
        />
        <div className="flex-1 min-h-0 overflow-y-auto relative z-10">
          {tab === "chest" && (() => {
            const allStationStages = Object.keys(STATIONS).map(Number).sort((a, b) => a - b);
            const isVisited = (stageId) => stages.find((s) => s.id === stageId)?.status === "done";
            const visitedCount = allStationStages.filter(isVisited).length;
            const allVisited = visitedCount === allStationStages.length;
            return (
              <div className="flex flex-col items-center px-7 pt-8 pb-8 text-center">
                <p style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 20 }} className="mb-1">المكافآت</p>
                <p className="text-xs mb-6" style={{ color: "#7A8496" }}>
                  {allVisited ? "زرت كل محطات الرحلة! ✦ انتقل إلى الجوائز لرؤية خاتمتها" : `زُرت من محطات الرحلة — ${visitedCount} من ${allStationStages.length}`}
                </p>
                <div className="grid grid-cols-3 gap-3 w-full mb-4">
                  {allStationStages.map((stageId) => {
                    const got = isVisited(stageId);
                    const st = STATIONS[stageId];
                    return (
                      <div key={stageId} className="rounded-2xl py-4 flex flex-col items-center gap-1.5" style={{ background: got ? "#FFF1D9" : "#FAFAFA", border: `1.5px ${got ? "solid" : "dashed"} ${got ? "#EFB84E" : "#E3E6EA"}` }}>
                        <span style={{ fontSize: 20 }}>{got ? "📍" : "❔"}</span>
                        <span style={{ fontSize: 11, fontWeight: 700, fontFamily: "'Amiri', serif", color: got ? "#8A5A12" : "#98A0AC" }}>{got ? st.name : "؟؟؟"}</span>
                      </div>
                    );
                  })}
                </div>
                {allVisited && (
                  <div className="fade-in rounded-2xl px-5 py-3 w-full" style={{ background: "#FFF1D9", border: "1.5px solid #EFB84E" }}>
                    <p style={{ fontSize: 13, color: "#8A5A12", fontWeight: 700 }}>✦ تهانينا! أتممت رحلة سفينة الإعراب كاملةً</p>
                  </div>
                )}
              </div>
            );
          })()}

          {tab === "trophies" && (() => {
            const allStationStages = Object.keys(STATIONS).map(Number).sort((a, b) => a - b);
            const isVisited = (stageId) => stages.find((s) => s.id === stageId)?.status === "done";
            const allVisited = allStationStages.every(isVisited);
            return (
              <div className="flex flex-col items-center px-7 pt-8 pb-8 text-center">
                <p style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 20 }} className="mb-1">الجوائز</p>
                <p className="text-xs mb-6" style={{ color: "#7A8496" }}>{allVisited ? "خاتمة رحلتك الكاملة من ريسوت إلى صور" : "تُفتح خاتمة الرحلة بعد زيارة كل المحطات"}</p>
                <div
                  className="rounded-2xl py-8 px-6 w-full flex flex-col items-center gap-3"
                  style={{ background: allVisited ? "linear-gradient(160deg,#FFF1D9,#FCEBC2)" : "#FAFAFA", border: `1.5px solid ${allVisited ? "#EFB84E" : "#E3E6EA"}` }}
                >
                  <span style={{ fontSize: 40, filter: allVisited ? "none" : "grayscale(1)", opacity: allVisited ? 1 : 0.35 }}>🏆</span>
                  {allVisited ? (
                    <p className="text-xs leading-relaxed" style={{ color: "#8A5A12", fontFamily: "'Amiri', serif", fontWeight: 700 }}>
                      {allStationStages.map((id) => STATIONS[id].name).join(" ← ")}
                    </p>
                  ) : (
                    <span style={{ fontSize: 10, color: "#98A0AC" }}>مقفل — أكمل زيارة كل المحطات أولاً</span>
                  )}
                </div>
              </div>
            );
          })()}

          {(tab === "challenges" || tab === "profile") && (
            <div className="flex flex-col items-center justify-center text-center px-8 h-full min-h-[500px]">
              {tab === "challenges" && <Swords size={40} color="#D8B24A" className="mb-4" />}
              {tab === "profile" && <User size={40} color="#D8B24A" className="mb-4" />}
              <p style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700, fontSize: 20 }} className="mb-2">
                {tab === "challenges" && "التحديات"}
                {tab === "profile" && "الملف الشخصي"}
              </p>
              <p className="text-sm" style={{ color: "#7A8496" }}>قيد الإعداد حاليًا في مشروعنا</p>
            </div>
          )}

          {tab === "home" && (
          <div className="relative">
          {levelComplete ? (
            <div className="text-center py-14 px-7 fade-in">
              <p style={{ fontSize: 44 }} className="mb-3">🏆</p>
              <p className="text-2xl mb-2" style={{ color: "#202430", fontFamily: "'Amiri', serif", fontWeight: 700 }}>
                أتممت {LEVELS.find((l) => l.id === currentLevel)?.name}!
              </p>
              <p className="text-sm mb-8" style={{ color: "#545B68" }}>
                {LEVELS.find((l) => l.id === currentLevel + 1)
                  ? `أحسنت! ${LEVELS.find((l) => l.id === currentLevel + 1)?.name} بانتظارك الآن`
                  : "أتممت كل مستويات سفينة الإعراب الحالية!"}
              </p>
              {LEVELS.find((l) => l.id === currentLevel + 1) ? (
                <button onClick={goToNextLevel} className="px-8 py-3.5 rounded-full text-sm font-bold inline-flex items-center gap-2" style={{ background: "linear-gradient(135deg,#F5A623,#D9860F)", color: "#2A1608" }}>
                  الانتقال إلى {LEVELS.find((l) => l.id === currentLevel + 1)?.name} <ChevronLeft size={15} />
                </button>
              ) : (
                <p className="text-xs" style={{ color: "#98A0AC" }}>المستويات القادمة قيد الإعداد</p>
              )}
            </div>
          ) : (
          <>
          {screen === "stage1" && <SortDragGame sfx={sfx} usedWords={usedWords} onWordsUsed={markWordsUsed} onFinish={(stars) => finishStage(1, stars)} />}
          {screen === "stage2" && <MatchGame sfx={sfx} usedWords={usedWords} onWordsUsed={markWordsUsed} onFinish={(stars) => finishStage(2, stars)} />}
          {screen === "stage3" && <SignsDragGame sfx={sfx} onFinish={(stars) => finishStage(3, stars)} eyebrow="سفينة الإعراب · التأسيس" title="علامات الاسم" words={NOUN_SIGN_WORDS} signsFor={nounSigns} />}
          {screen === "stage4" && <SignsDragGame sfx={sfx} onFinish={(stars) => finishStage(4, stars)} eyebrow="سفينة الإعراب · التأسيس" title="علامات الفعل" words={VERB_SIGN_WORDS} signsFor={verbSigns} />}
          {screen === "stage5" && <NakiraGame sfx={sfx} onFinish={(stars) => finishStage(5, stars)} />}
          {screen === "stage6" && <FirasaGame sfx={sfx} onFinish={(stars) => finishStage(6, stars)} />}
          {screen === "stage7" && <AzminaGame sfx={sfx} onFinish={(stars) => finishStage(7, stars)} />}
          {screen === "stage8" && <ConstructGame sfx={sfx} onFinish={(stars) => finishStage(8, stars)} />}
          {screen === "stage9" && <TransformGame sfx={sfx} onFinish={(stars) => finishStage(9, stars)} />}
          {screen === "stage10" && <FaeilGame sfx={sfx} onFinish={(stars) => finishStage(10, stars)} />}
          {screen === "stage11" && <KanaGame sfx={sfx} onFinish={(stars) => finishStage(11, stars)} />}

          {screen === "map" && (() => {
            const levelDef = LEVELS.find((l) => l.id === currentLevel);
            const levelStages = stages.filter((s) => s.id >= levelDef.range[0] && s.id <= levelDef.range[1]);
            const camelStageId = levelDef.range[0] + camelIndex;
            const camelStation = STATIONS[camelStageId] || STATIONS[levelDef.range[0]];
            return (
            <>
              <div className="px-6 pt-7 pb-2 text-center relative">
                <button
                  onClick={() => setAdminMode((m) => !m)}
                  className="absolute top-4 left-4 flex items-center gap-1.5 px-3 py-1.5 rounded-full text-[10px] font-bold z-40"
                  style={{
                    background: adminMode ? "rgba(74,222,128,0.2)" : "#F5F5F7",
                    border: `1.5px solid ${adminMode ? "#4ADE80" : "#DDD8E8"}`,
                    color: adminMode ? "#4ADE80" : "#545B68",
                  }}
                >
                  <ShieldCheck size={12} /> {adminMode ? "وضع المدير: مفعّل" : "وضع المدير"}
                </button>
                <p className="text-xs font-bold" style={{ color: "#D9860F", fontFamily: "'Amiri', serif", letterSpacing: "0.1em" }}>{levelDef.name}</p>
              </div>

              <div className="px-4 pb-8 pt-3">
                <div className="relative mx-auto rounded-2xl overflow-hidden" style={{ width: "100%", maxWidth: 340, paddingTop: "175%", boxShadow: "0 8px 24px -8px rgba(0,0,0,0.35)", background: "#EFE6D2" }}>
                <div className="absolute inset-0">
                  <img src={OMAN_MAP_IMG} alt="خريطة عُمان" className="absolute inset-0 w-full h-full object-cover" style={{ opacity: 0.22 }} />
                  {(() => {
                    const fullPathD = levelStages
                      .map((s, i) => {
                        const st = STATIONS[s.id];
                        return `${i === 0 ? "M" : "L"} ${st.x * 100},${st.y * 100}`;
                      })
                      .join(" ");
                    return (
                      <>
                        <svg className="absolute inset-0 w-full h-full" viewBox="0 0 100 100" preserveAspectRatio="none">
                          <path d={fullPathD} fill="none" stroke="#8B2635" strokeWidth="0.6" strokeDasharray="0.2,1.6" strokeLinecap="round" opacity="0.9" />
                        </svg>
                        {levelStages.map((stage) => {
                          const isDone = stage.status === "done";
                          const isCurrent = stage.status === "current";
                          const isLocked = stage.status === "locked" && !adminMode;
                          const st = STATIONS[stage.id];
                          return (
                            <button
                              key={stage.id}
                              onClick={() => tapStage(stage)}
                              className={`absolute flex flex-col items-center ${isCurrent ? "pulse-glow-stage" : ""}`}
                              style={{ left: `${st.x * 100}%`, top: `${st.y * 100}%`, transform: "translate(-50%,-100%)", width: 70 }}
                            >
                              {/* دبّوس موقع (كالخرائط الحقيقية) — يظهر دومًا، والاسم يُكشف فقط بعد الوصول */}
                              <svg width={isLocked ? 20 : 26} height={isLocked ? 26 : 34} viewBox="0 0 26 34" style={{ filter: "drop-shadow(0 2px 3px rgba(0,0,0,0.35))", opacity: isLocked ? 0.55 : 1 }}>
                                <path
                                  d="M13 0C5.8 0 0 5.8 0 13c0 9 13 21 13 21s13-12 13-21C26 5.8 20.2 0 13 0Z"
                                  fill={isLocked ? "#B8B0C0" : isDone ? "#EFB84E" : "#F5A623"}
                                  stroke="#8B2635" strokeWidth="1.2"
                                />
                                <circle cx="13" cy="13" r="5.5" fill="#FFFFFF" />
                              </svg>
                              {!isLocked && (
                                <p className="-mt-1 text-[10px] px-2 py-0.5 rounded-full whitespace-nowrap" style={{ background: "#FFF3D6", color: "#2A1608", fontFamily: "'Amiri', serif", fontWeight: 700, border: "1px solid #8B2635" }}>
                                  {st.name}
                                </p>
                              )}
                              {isDone && (
                                <div className="flex gap-0.5 mt-0.5">
                                  {[0, 1, 2].map((s) => <Star key={s} size={7} color={s < stage.stars ? "#F5A623" : "#E3E6EA"} fill={s < stage.stars ? "#F5A623" : "none"} />)}
                                </div>
                              )}
                            </button>
                          );
                        })}
                      </>
                    );
                  })()}

                  <div
                    className="absolute camel-bob"
                    style={{
                      left: `${camelStation.x * 100}%`,
                      top: `${camelStation.y * 100}%`,
                      fontSize: 26,
                      filter: "drop-shadow(0 3px 5px rgba(0,0,0,0.4))",
                      transition: "left 1.3s ease-in-out, top 1.3s ease-in-out",
                      animationDuration: walking ? "0.5s" : "2.2s",
                    }}
                  >
                    <span style={{ display: "inline-block", transform: "scaleX(-1)" }}>🐫</span>
                  </div>
                </div>
                </div>
              </div>

              {toast && (
                <div className="toast-in absolute bottom-6 left-1/2 z-30 px-5 py-2.5 rounded-full text-xs flex items-center gap-2 whitespace-nowrap" style={{ background: "rgba(20,15,35,0.92)", color: "#FFF6DE", border: "1px solid rgba(255,215,120,0.4)" }}>
                  {toast}
                </div>
              )}
            </>
            );
          })()}
          </>
          )}
          </div>
          )}
        </div>

        {/* شريط المهام السفلي */}
        <div className="flex items-stretch border-t z-20 flex-shrink-0" style={{ borderColor: "#EFB84E", background: "#FFFFFF" }}>
          {[
            { key: "home", label: "الرئيسية", Icon: Home },
            { key: "chest", label: "المكافآت", Icon: Gift },
            { key: "trophies", label: "الجوائز", Icon: Trophy },
            { key: "challenges", label: "التحديات", Icon: Swords },
            { key: "profile", label: "الملف الشخصي", Icon: User },
          ].map(({ key, label, Icon }) => {
            const active = tab === key;
            return (
              <button
                key={key}
                onClick={() => setTab(key)}
                className="flex-1 flex flex-col items-center gap-1 py-2.5"
                style={{ color: active ? "#D9860F" : "#98A0AC" }}
              >
                <Icon size={20} strokeWidth={active ? 2.4 : 2} fill={active && key !== "home" ? "#FFDDA6" : "none"} />
                <span style={{ fontSize: 9, fontWeight: active ? 700 : 500 }}>{label}</span>
              </button>
            );
          })}
        </div>
        </>
        )}
      </div>
    </div>
  );
}
